      );
      expect(git(root, 'rev-parse', 'main')).toBe(targetBefore);
      for (const childRoot of childRoots) expect(await fs.stat(childRoot)).toBeDefined();
      expect(await fs.stat(worktree)).toBeDefined();
      return;
    }
    const accepted = await cli(
