      verifierExecutionRef: 'verifier-correction',
      response: {
        kind: 'final-result',
        result: {
          iteration: invalid === 'position' ? state.loop.iteration + 1 : state.loop.iteration,
          attempt: invalid === 'position' ? state.loop.attempt + 1 : state.loop.attempt,
