      }),
    ).rejects.toMatchObject({ code: 'OUTCOME_PROCESSING_ERROR' });
    const rejected = await f.runtime.inspect(f.run.runId);
    expect(rejected.actions.at(-1)).toMatchObject({
      id: original.id,
