      );
      const handoff = (run.state as NativePortableState).builder_handoff!;
      expect(handoff.addressed_acceptance_ids).toEqual(submittedAt === undefined ? [] : ['A1']);
      expect(handoff.acceptance_review).toHaveLength(1);
