    );
    await fs.writeFile(target, revisedTarget);
    await collectProposal(f.paths, f.initialState, true);
    expect(await fs.readFile(target, 'utf8')).toBe(revisedTarget);
    expect(await fs.readFile(target, 'utf8')).toContain(
