    await fs.writeFile(deltaFile, JSON.stringify(delta));
    await expect(collectProposal(f.paths, f.initialState, true)).rejects.toThrow(
      /independent|独立/iu,
    );
    expect(await fs.readFile(target, 'utf8')).toBe(independent);
  });

