  const f = await fixture();
  await f.submitBuilder(f.pending(f.run, 'build.builder'), 'NEEDS-REQUIREMENTS\n');
  await f.native(['next', f.name]);
  let run = await f.dispatch({ operation: 'inspect', runId: f.name });
