  );
  run = await f.dispatch({
    operation: 'execute',
    runId: f.name,
    actionId: f.pending(run, 'native.extension.candidate.candidate-review').id,
    executorId: 'native-review-script',
  });
  expect(
    run.waits.some(
      (wait) => wait.status === 'pending' && wait.stepId.startsWith('native.extension.revise.'),
