      expect(
        execFileSync('git', ['status', '--porcelain', '--untracked-files=all'], {
          cwd: supervisor.integration.worktree,
          encoding: 'utf8',
        }),
      ).toBe('');
      const failed = await applyNativeRunnerInput({
        paths,
        name: 'parent',
        maxVerifyFailures: 5,
